-- 시연용 문서함 자료 (명세 7장, DEC-098, slices/21 8장, slices/22 4.3, DEC-144). scripts/demo-docbox-data.py가 만든 파일이다. 직접 고치지 않는다
-- 정보통신대대·정보통신상황실·1중대·유선반·무선반 문서함: 폴더 5개, 파일 19개(무선반 휴지통에 파일 1·폴더 1, 지운 폴더 안 파일 1), 공유 6개(부서 5(폴더 1), 사람 1). 내용은 모두 가상(NFR-002)
-- hwp·hwpx·pdf 세 파일은 앞 판의 바이트를 그대로 다시 쓴 것이고, docx·xlsx·pptx·txt·png는 표준 라이브러리로 만든 것이다
-- 이름이 R__seed_work_docbox_demo라 초기 데이터·시연 업무·지시사항 다음에 돈다. 문서함에 무엇이든 있거나 번호 범위(200001~200999)가 쓰였거나
-- 쓸 계정이 없으면 전체를 건너뛴다. 휴지통은 지운 노드에만 trashed_at·trashed_by(서버와 같음)
-- 시각은 시연 기준 시각(KST, 고정)에서 뺀 값이다(평일 근무 시간, 가장 늦은 것 11-18 16:40)

SET @base = TIMESTAMP('2026-11-19 09:00:00');
SET @a_bn1_cmdr = (SELECT id FROM account WHERE login_id = 'bn1-cmdr' AND active = TRUE);
SET @a_bn1_co1_admin = (SELECT id FROM account WHERE login_id = 'bn1-co1-admin' AND active = TRUE);
SET @a_bn1_co1_cmdr = (SELECT id FROM account WHERE login_id = 'bn1-co1-cmdr' AND active = TRUE);
SET @a_bn1_co1_s1_lead = (SELECT id FROM account WHERE login_id = 'bn1-co1-s1-lead' AND active = TRUE);
SET @a_bn1_co1_s1_m1 = (SELECT id FROM account WHERE login_id = 'bn1-co1-s1-m1' AND active = TRUE);
SET @a_bn1_co1_s2_lead = (SELECT id FROM account WHERE login_id = 'bn1-co1-s2-lead' AND active = TRUE);
SET @a_bn1_co1_s2_m1 = (SELECT id FROM account WHERE login_id = 'bn1-co1-s2-m1' AND active = TRUE);
SET @a_bn1_co1_s2_m3 = (SELECT id FROM account WHERE login_id = 'bn1-co1-s2-m3' AND active = TRUE);
SET @a_bn1_dual = (SELECT id FROM account WHERE login_id = 'bn1-dual' AND active = TRUE);
SET @a_bn1_hq_s1_lead = (SELECT id FROM account WHERE login_id = 'bn1-hq-s1-lead' AND active = TRUE);
SET @a_bn1_hq_s1_m1 = (SELECT id FROM account WHERE login_id = 'bn1-hq-s1-m1' AND active = TRUE);
SET @a_bn2_cmdr = (SELECT id FROM account WHERE login_id = 'bn2-cmdr' AND active = TRUE);
SET @ok = (SELECT COUNT(*) FROM doc_node) = 0
    AND (SELECT COUNT(*) FROM stored_file WHERE id BETWEEN 200001 AND 200999) = 0
    AND (SELECT COUNT(*) FROM doc_share WHERE id BETWEEN 200001 AND 200999) = 0
    AND @a_bn1_cmdr IS NOT NULL
    AND @a_bn1_co1_admin IS NOT NULL
    AND @a_bn1_co1_cmdr IS NOT NULL
    AND @a_bn1_co1_s1_lead IS NOT NULL
    AND @a_bn1_co1_s1_m1 IS NOT NULL
    AND @a_bn1_co1_s2_lead IS NOT NULL
    AND @a_bn1_co1_s2_m1 IS NOT NULL
    AND @a_bn1_co1_s2_m3 IS NOT NULL
    AND @a_bn1_dual IS NOT NULL
    AND @a_bn1_hq_s1_lead IS NOT NULL
    AND @a_bn1_hq_s1_m1 IS NOT NULL
    AND @a_bn2_cmdr IS NOT NULL;

